import openpyxl
wb = openpyxl.load_workbook('项目费用预算清单-自动统计1_inconsistent_color_6447_input.xlsx')
ws = wb['Sheet1']
# dump every cell in used range with its fill info
for row in ws.iter_rows():
    for c in row:
        fill = c.fill
        patt = fill.patternType
        info = f"{c.coordinate}: pattern={patt}"
        if fill.fgColor is not None:
            fg = fill.fgColor
            if fg.type == 'rgb':
                info += f" fg_rgb={fg.rgb}"
            elif fg.type == 'theme':
                info += f" fg_theme={fg.theme} tint={fg.tint}"
            elif fg.type == 'indexed':
                info += f" fg_indexed={fg.indexed}"
            else:
                info += f" fg_type={fg.type} rgb={fg.rgb}"
        if fill.bgColor is not None:
            bg = fill.bgColor
            if bg.type == 'rgb':
                info += f" bg_rgb={bg.rgb}"
            elif bg.type == 'theme':
                info += f" bg_theme={bg.theme} tint={bg.tint}"
            elif bg.type == 'indexed':
                info += f" bg_indexed={bg.indexed}"
            else:
                info += f" bg_type={bg.type} rgb={bg.rgb}"
        print(info)
