import openpyxl
wb = openpyxl.load_workbook('项目费用预算清单-自动统计1_inconsistent_color_6447_input.xlsx')
ws = wb['Sheet1']
print('max_row', ws.max_row, 'max_col', ws.max_column)
# Scan all cells up to max_row+5 and max_col+5 for non-default fills
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=1, max_col=ws.max_column):
    for c in row:
        fill = c.fill
        if fill.patternType is None:
            continue
        fg = fill.fgColor
        if fg.type == 'rgb':
            info = f"rgb={fg.rgb}"
        elif fg.type == 'theme':
            info = f"theme={fg.theme} tint={fg.tint}"
        else:
            info = f"type={fg.type} rgb={fg.rgb}"
        print(c.coordinate, 'pattern=', fill.patternType, info)
EOF

